const TAPU_AKTARIM_ISARETI='tapu_excel_aktarim_v1';
function tapuHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function tapuMetin(v){return String(v??'').toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');}
function tapuSayisal(v){const n=Number(v);return Number.isFinite(n)?n:0;}
function tapuAlan(v){return new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(tapuSayisal(v));}
function tapuTarih(v){if(!v)return '-';const p=String(v).slice(0,10).split('-');return p.length===3?`${p[2]}.${p[1]}.${p[0]}`:String(v);}
function tapuYazabilir(){return typeof anaMenuModulYazmaYetkisiVar==='function'?anaMenuModulYazmaYetkisiVar('tapu'):true;}
function tapuYeniId(){return 'tapu_'+Date.now()+'_'+Math.random().toString(36).slice(2,8);}
function tapuParselUrlDogrula(v){let s=String(v||'').trim();if(!s)return '';s=s.replace(/^https:\/\/parselsorgu\.tkgm\.gov\.tr\/ara\//i,'https:\x2f\x2fparselsorgu.tkgm.gov.tr/#ara/');try{const u=new URL(s);return u.protocol==='https:'&&u.hostname==='parselsorgu.tkgm.gov.tr'?u.href:'';}catch(_){return '';}}
function tapuDosyaMime(dosya){const u=String(dosya?.name||'').split('.').pop().toLowerCase(),m={pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp'};return m[u]||'';}
function tapuHataMetni(error){const m=String(error?.message||error||'Kayıt işlemi tamamlanamadı.');if(m.includes('portal_records_module_check'))return 'Tapu Takip veritabanı tanımı henüz etkin değil. Güncel veritabanı dosyasını uygulayın.';return m;}
async function tapuVerileriniYukle(zorla=false){
const fdTitleIdentity=fdTitleDataContext();

 if(!SUPABASE_MODE||!supabaseClient||!activeUser?.sirketId)throw new Error('Kayıt bağlantısı hazır değil.');
 const imzaAnahtari=fdUzakImzaAnahtari('taputakip',new Date().getFullYear());if(!zorla&&Array.isArray(window.fdTapuTumSatirlari)&&fdUzakVeriImzalari.has(imzaAnahtari)){const guncel=await fdTitleDataAwait(fdUzakAnahtarImzasiniPaylasimliGetir('taputakip',new Date().getFullYear()),fdTitleIdentity);if(fdUzakVeriImzalari.get(imzaAnahtari)===guncel)return;}
 const tum=[];for(let bas=0;;bas+=500){const {data,error}=await fdTitleDataAwait(supabaseClient.from('portal_records').select('legacy_id,data,updated_at').eq('company_id',activeUser.sirketId).eq('module','taputakip').order('legacy_id').range(bas,bas+499),fdTitleIdentity);if(error)throw error;const parca=data||[];tum.push(...parca);if(parca.length<500)break;}
 window.fdTapuTumSatirlari=tum;tapuAktarimTamam=tum.some(x=>String(x.legacy_id)===TAPU_AKTARIM_ISARETI);tapuCksAktarimTamam=tum.some(x=>String(x.legacy_id)===TAPU_CKS_AKTARIM_ISARETI);tapuKayitlari=tum.filter(x=>x?.data?.kayitTipi==='tapu').map(x=>({...x.data,id:String(x.data.id||x.legacy_id)}));tapuCksKayitlari=tum.filter(x=>x?.data?.kayitTipi==='cks').map(x=>({...x.data,id:String(x.data.id||x.legacy_id)}));fdUzakImzayiSatirlardanKaydet('taputakip',new Date().getFullYear(),tum);
}
async function tapuExcelKayitlariniAktar(kullaniciIstegi=false){
const fdTitleIdentity=fdTitleDataContext();

 if(!tapuYazabilir())return showToast?.('Bu modülde kayıt yetkiniz yok.','warning');
 if(kullaniciIstegi&&!confirm('Excel listesindeki 280 kayıt mevcut kayıtlarla eşleştirilerek aktarılacak. Devam edilsin mi?'))return;
 const btn=document.getElementById('tapuExcelAktarBtn'),bar=document.getElementById('tapuAktarimProgress'),fill=bar?.querySelector('span');if(btn){btn.disabled=true;btn.textContent='Aktarılıyor...';}if(bar)bar.style.display='block';
 try{const satirlar=TAPU_EXCEL_KAYITLARI.map(k=>({company_id:activeUser.sirketId,module:'taputakip',legacy_id:String(k.id),record_year:Number(String(k.alisTarihi||'').slice(0,4))||new Date().getFullYear(),employee_legacy_id:null,data:k}));satirlar.push({company_id:activeUser.sirketId,module:'taputakip',legacy_id:TAPU_AKTARIM_ISARETI,record_year:new Date().getFullYear(),employee_legacy_id:null,data:{kayitTipi:'aktarim',surum:1,tarih:new Date().toISOString(),kayitSayisi:TAPU_EXCEL_KAYITLARI.length}});for(let i=0;i<satirlar.length;i+=75){const {error}=await fdTitleDataAwait(supabaseClient.from('portal_records').upsert(satirlar.slice(i,i+75),{onConflict:'company_id,module,legacy_id'}),fdTitleIdentity);if(error)throw error;if(fill)fill.style.width=Math.round(Math.min(i+75,satirlar.length)/satirlar.length*100)+'%';}await fdTitleDataAwait(tapuVerileriniYukle(),fdTitleIdentity);tapuEkraniniCiz();showToast?.('280 tapu kaydı başarıyla aktarıldı.');}
 catch(error){
if(fdTitleIdentity!==fdTitleDataContext())return;
console.error('Tapu toplu aktarım:',error);alert('Tapu kayıtları aktarılamadı: '+tapuHataMetni(error));}
 finally{if(btn){btn.disabled=false;btn.textContent='↥ Mevcut Listeyi Aktar';}setTimeout(()=>{if(bar)bar.style.display='none';if(fill)fill.style.width='0';},500);tapuYetkiGorunumunuAyarla();}
}
